package com.autoops.auth.controller;import com.autoops.auth.dto.AuthDtos;import com.autoops.auth.service.AuthService;import com.autoops.common.security.CurrentUser;import com.autoops.user.repository.UserRepository;import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.http.ResponseCookie;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/auth")public class AuthController{private final AuthService service;private final CurrentUser current;private final UserRepository users;public AuthController(AuthService s,CurrentUser c,UserRepository u){service=s;current=c;users=u;}@PostMapping("/login")public AuthDtos.AuthResponse login(@Valid @RequestBody AuthDtos.LoginRequest r,HttpServletResponse res){var s=service.login(r);cookie(res,s.refreshToken(),604800);return s.response();}@PostMapping("/refresh")public AuthDtos.AuthResponse refresh(@CookieValue(name="autoops_refresh")String token,HttpServletResponse res){var s=service.refresh(token);cookie(res,s.refreshToken(),604800);return s.response();}@PostMapping("/logout")public void logout(@CookieValue(name="autoops_refresh",required=false)String token,HttpServletResponse res){service.logout(token);cookie(res,"",0);}@GetMapping("/me")public AuthDtos.MeResponse me(){var u=users.findById(current.id()).orElseThrow();return new AuthDtos.MeResponse(u.getId(),u.getUsername(),u.getRole().name());}private void cookie(HttpServletResponse res,String value,long age){res.addHeader("Set-Cookie",ResponseCookie.from("autoops_refresh",value).httpOnly(true).secure(true).sameSite("Strict").path("/api/auth").maxAge(age).build().toString());}}
